package local.skyfamily;
import android.app.AlertDialog;import android.content.*;import android.graphics.*;import android.os.*;import android.text.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
public class RefinedActivity extends AutoCastActivity {
 static final int BOOK_PICK=974;LinearLayout petDock;
 @Override public void onContentChanged(){super.onContentChanged();petDock=null;if(corner!=null){if(corner.getParent() instanceof ViewGroup)((ViewGroup)corner.getParent()).removeView(corner);corner=null;}}
 @Override void page(String title){super.page(title);if(sidebar!=null){while(sidebar.getChildCount()>1)sidebar.removeViewAt(1);String selected=group(title);frameRail("Home",selected.equals("Home"),()->home());frameRail("Photos",selected.equals("Photos"),()->framePhotos());frameRail("School",selected.equals("School"),()->schoolHome());frameRail("Games",selected.equals("Games"),()->puzzle());frameRail("Explore",selected.equals("Explore"),()->frameExplore());frameRail("Uploads",selected.equals("Uploads"),()->uploadHub());frameRail("Apps",title.equals("Apps"),()->apps());frameRail("Settings",selected.equals("Settings"),()->settings());compactShell();}if(body!=null&&body.getParent() instanceof ScrollView){ViewGroup host=(ViewGroup)((View)body.getParent()).getParent();if(host instanceof LinearLayout){petDock=new LinearLayout(this);petDock.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);PetSprite sprite=new PetSprite(this,animal());petDock.addView(sprite,new LinearLayout.LayoutParams(dp(76),dp(56)));host.addView(petDock,new LinearLayout.LayoutParams(-1,dp(56)));updateDock();}}}
 void updateDock(){if(petDock==null)return;boolean show=resumed&&!hidden&&!focusEligible()&&frame==null&&prefs.getBoolean("pet.dock",true);int visibility=show?View.VISIBLE:View.GONE;if(petDock.getVisibility()!=visibility)petDock.setVisibility(visibility);}
 void card(String title,String detail,Runnable action){tile(title,detail,"",accent,action);}
 @Override void home(){page("Today");header.setVisibility(View.GONE);TextClock clock=new TextClock(this);clock.setFormat12Hour("h:mm a");clock.setFormat24Hour("HH:mm");clock.setTextColor(INK);clock.setTextSize(52);clock.setTypeface(Typeface.create("sans-serif-condensed",Typeface.BOLD));body.addView(clock);body.addView(paperText(new java.text.SimpleDateFormat("EEEE, d MMMM",Locale.getDefault()).format(new Date()),22,INK));body.addView(weatherSummary());LinearLayout overview=new LinearLayout(this);boolean wide=getResources().getConfiguration().screenWidthDp>=760;overview.setOrientation(wide?0:1);body.addView(overview);addPanel(overview,todayPanel(),1,wide);addPanel(overview,agendaPanel(),1,wide);section("Your day");card("School","Class notebooks and assignments",()->schoolHome());card("Albums","Photos, selections and galleries",()->framePhotos());card("Notes","Daily notes and reminders",()->notes());card("Calendar","Local day entries",()->calendar());endgrid();section("Explore");card("Explore","Wildlife, aquariums, planetarium and Weather TV",()->frameExplore());card("Books","Bookshelf and PDF documents",()->bookshelf());card("Create","Drawing, colouring and projects",()->frameCreate());card("Games","Arcade, words and your virtual pet",()->puzzle());card("Uploads","Receive files or add to your bookshelf",()->uploadHub());card("Apps","Installed applications",()->apps());endgrid();body.addView(photoPanel());ArrayList<String> birthdays=ThemeArt.today(prefs);if(!birthdays.isEmpty())text("Happy birthday, "+TextUtils.join(", ",birthdays)+"!");shownDay=ThemeArt.dateKey(Calendar.getInstance());atHome=true;armIdle();updateDock();}
 @Override LinearLayout weatherSummary(){LinearLayout panel=paperPanel("Local forecast");try{JSONObject place=new JSONObject(get("planetary.location")),cache=new JSONObject(get("planetary.cache"));if(!(place.optString("latitude")+","+place.optString("longitude")).equals(cache.optString("place")))throw new Exception();JSONObject current=cache.getJSONObject("data").getJSONObject("current");double value=current.optDouble("temperature_2m",Double.NaN);LinearLayout reading=new LinearLayout(this);reading.setGravity(Gravity.CENTER_VERTICAL);TextView temperature=paperText(Double.isNaN(value)||Double.isInfinite(value)?"Unavailable":String.format(Locale.US,"%.0f°F",value),50,INK);temperature.setSingleLine(true);reading.addView(temperature,new LinearLayout.LayoutParams(-2,-2));WeatherMotion symbol=new WeatherMotion(this,current.optInt("weather_code",-1),current.optInt("is_day",1)==1,prefs.getBoolean("weather.motion",true));LinearLayout.LayoutParams icon=new LinearLayout.LayoutParams(dp(60),dp(60));icon.leftMargin=dp(10);reading.addView(symbol,icon);reading.addOnLayoutChangeListener((view,l,t,r,b,ol,ot,or,ob)->{float base=50*getResources().getDisplayMetrics().scaledDensity;Paint measure=new Paint(temperature.getPaint());measure.setTextSize(base);float room=Math.max(dp(60),reading.getWidth()-dp(70)),needed=measure.measureText(temperature.getText().toString());float size=base*Math.min(1,room/Math.max(1,needed));if(Math.abs(temperature.getTextSize()-size)>.5f)temperature.setTextSize(android.util.TypedValue.COMPLEX_UNIT_PX,size);});panel.addView(reading);panel.addView(paperText(new PlanetaryPanel(this).condition(current.optInt("weather_code",-1)),18,INK));panel.addView(paperText(new PlanetaryPanel(this).label(place),16,MUTE));long fetched=cache.optLong("fetched"),age=System.currentTimeMillis()-fetched;panel.addView(paperText((age<0||age>=900000?"STALE CACHE / ":"Cached forecast / ")+new Date(fetched),14,MUTE));}catch(Exception error){panel.addView(paperText(get("planetary.location").isEmpty()?"Choose your location":"Weather unavailable",24,INK));}panel.addView(paperText("Open forecast >",16,INK));panel.setFocusable(true);panel.setOnClickListener(view->planetaryData());return panel;}
 @Override void schoolHome(){page("School");card("Agenda","Open and completed assignments",()->agenda(0,""));card("Search notes","Find titles and typed schoolwork",()->schoolSearch());card("New notebook","Add a class or subject",()->nameNotebook(""));card("Export school data","Save a JSON copy of local schoolwork",()->exportSchool());endgrid();section("Class notebooks");attempt(()->{JSONArray rows=db().rows("SELECT * FROM notebooks ORDER BY name COLLATE NOCASE");for(int i=0;i<rows.length();i++){JSONObject notebook=rows.optJSONObject(i);if(notebook==null)throw new IllegalStateException("Invalid notebook row");card(notebook.optString("name"),"Open notes and assignments",()->notebook(notebook.optString("id")));}endgrid();});if(!unsaved.isEmpty())text("NOT SAVED: some school drafts remain only in memory. Keep the app open and resolve storage before closing.");}
 @Override void notebook(String id){page("Class notebook");JSONObject notebook=db().one("notebooks",id);if(notebook==null){schoolHome();return;}section(notebook.optString("name"));card("New school note","Type and draw on a saved page",()->attempt(()->schoolNote(db().page(id))));card("Assignments","Agenda for this class",()->agenda(0,id));card("Rename notebook","Change the class label",()->nameNotebook(id));endgrid();section("Pages");JSONArray pages=db().rows("SELECT id,title,section FROM pages WHERE notebook=? ORDER BY section COLLATE NOCASE,updated DESC",id);for(int i=0;i<pages.length();i++){JSONObject page=pages.optJSONObject(i);card(page.optString("title"),page.optString("section"),()->schoolNote(page.optString("id")));}endgrid();if(pages.length()==0)text("No notes yet. Add a school note to start.");button("Back to School",()->schoolHome());if(!id.equals("general"))button("Delete notebook",()->new AlertDialog.Builder(this).setMessage("Delete this notebook, its pages and assignments? This cannot be undone.").setPositiveButton("Delete",(dialog,which)->attempt(()->{db().exec("DELETE FROM notebooks WHERE id=?",id);schoolHome();})).setNegativeButton("Cancel",null).show());}
 @Override void framePhotos(){page("Albums and photos");card(token.isEmpty()?"Connect Immich":"Photo library","Browse your actual photos and videos",()->immich());card("Choose albums","Select one or more Immich albums",()->albums());card("Play selected gallery","Use the saved album selection",()->startGallery(false));card("Uploaded photos","Browse files received on this device",()->uploads());card("Play uploaded gallery","Start local photo playback",()->startGallery(true));card("Gallery settings","Timing, shuffle and idle playback",()->gallerySettings());endgrid();}
 @Override void uploadHub(){page("Uploads");card("Receive from phone","QR session on all IPv4 interfaces",()->uploadAddress());card("Add to bookshelf","Choose a file; its format is detected automatically",()->importBook());card("Uploaded photos","Browse received images",()->uploads());card("Bookshelf","Read imported books and PDFs",()->bookshelf());card("Art projects","Continue saved artwork",()->projectsEntry());endgrid();text("QR upload uses unencrypted HTTP and a temporary secret URL: trusted LAN only. Import trusted PDFs/books only.");}
 @Override void notes(){page("Daily notes");LinearLayout panel=paperPanel("Daily note");body.addView(panel);EditText date=new EditText(this);date.setTextColor(INK);date.setHint("YYYY-MM-DD");date.setSingleLine(true);date.setText(new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date()));panel.addView(date,new LinearLayout.LayoutParams(-1,-2));EditText editor=new EditText(this);editor.setTextColor(INK);editor.setHintTextColor(MUTE);editor.setHint("Write a note");editor.setGravity(Gravity.TOP);editor.setMinLines(8);editor.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);editor.setText(get("note."+date.getText()));panel.addView(editor,new LinearLayout.LayoutParams(-1,-2));button("Load date",()->editor.setText(get("note."+date.getText())));button("Save daily note",()->{save("note."+date.getText(),editor.getText().toString());toast("Daily note saved");});}
 @Override boolean keyboardVisible(){View focus=getCurrentFocus();if(focus instanceof EditText){if(focus!=noteText||noteInk==null||!noteInk.writing)return true;}if(Build.VERSION.SDK_INT>=30){WindowInsets insets=getWindow().getDecorView().getRootWindowInsets();if(insets!=null&&insets.isVisible(WindowInsets.Type.ime()))return true;}Point screen=new Point();getWindowManager().getDefaultDisplay().getSize(screen);Rect visible=new Rect();getWindow().getDecorView().getWindowVisibleDisplayFrame(visible);return screen.y-visible.bottom>dp(120);}
 @Override void schoolNote(String id){super.schoolNote(id);if(id.equals(noteId)&&noteText!=null){noteText.setSelectAllOnFocus(false);noteText.setFocusableInTouchMode(true);noteText.setOnTouchListener((view,event)->{if(event.getActionMasked()==MotionEvent.ACTION_DOWN)view.getParent().requestDisallowInterceptTouchEvent(true);if(event.getActionMasked()==MotionEvent.ACTION_UP||event.getActionMasked()==MotionEvent.ACTION_CANCEL)view.getParent().requestDisallowInterceptTouchEvent(false);return false;});}}
 @Override void tool(LinearLayout row,String title,Runnable action){super.tool(row,title,()->{action.run();if(title.equals("Type")&&noteText!=null)noteText.requestFocus();else if(title.equals("Ink")){if(noteText!=null)noteText.clearFocus();if(noteTitle!=null)noteTitle.clearFocus();if(noteSection!=null)noteSection.clearFocus();}});}
 @Override void button(String title,Runnable action){String value=title.toLowerCase(Locale.US);if(value.startsWith("import epub")||value.equals("import book / pdf")){super.button("Add to bookshelf",()->importBook());return;}if(value.startsWith("open pdf / other school document"))return;super.button(title,action);}
 @Override void importBook(){Intent picker=new Intent(Build.VERSION.SDK_INT>=19?Intent.ACTION_OPEN_DOCUMENT:Intent.ACTION_GET_CONTENT);picker.addCategory(Intent.CATEGORY_OPENABLE);picker.setType("*/*");if(Build.VERSION.SDK_INT>=19)picker.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/pdf","application/epub+zip","text/plain"});try{startActivityForResult(Intent.createChooser(picker,"Add to bookshelf"),BOOK_PICK);}catch(Exception error){toast("File picker unavailable");}}
 @Override protected void onActivityResult(int request,int result,Intent data){if(request!=BOOK_PICK){super.onActivityResult(request,result,data);return;}if(result==RESULT_OK&&data!=null&&data.getData()!=null)BookImport.add(this,data.getData());}
 @Override void weatherTvIntro(){openWeatherTv();}
 @Override void openWeatherTv(){startActivity(new Intent(this,WeatherKioskActivity.class));}
 @Override void settings(){super.settings();CheckBox weatherMotion=new CheckBox(this);weatherMotion.setText("Animate weather-card symbols");weatherMotion.setChecked(prefs.getBoolean("weather.motion",true));body.addView(weatherMotion);weatherMotion.setOnCheckedChangeListener((button,checked)->prefs.edit().putBoolean("weather.motion",checked).apply());}
 @Override void normalize(View view){super.normalize(view);if(view instanceof LinearLayout){LinearLayout row=(LinearLayout)view;if(row.getChildCount()>1&&row.getChildAt(0) instanceof PlanetaryPanel.WeatherIcon){PlanetaryPanel.WeatherIcon old=(PlanetaryPanel.WeatherIcon)row.getChildAt(0);if(old.getLayoutParams().width>=dp(64)){row.removeViewAt(0);row.addView(new WeatherMotion(this,old.code,old.day,prefs.getBoolean("weather.motion",true)),0,new LinearLayout.LayoutParams(dp(64),dp(64)));row.setPadding(dp(16),dp(14),dp(16),dp(14));row.setBackground(controlBackground());if(row.getChildAt(1) instanceof LinearLayout){LinearLayout readings=(LinearLayout)row.getChildAt(1);readings.setPadding(dp(10),0,0,0);for(int i=0;i<readings.getChildCount();i++)if(readings.getChildAt(i) instanceof TextView){TextView label=(TextView)readings.getChildAt(i);label.setText(label.getText().toString().replace(" °F","°F"));}}}}}if(view==body||view.getId()==android.R.id.content)updateDock();}
 void weatherRunning(View view,boolean active){if(view instanceof WeatherMotion)((WeatherMotion)view).running(active);if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++)weatherRunning(group.getChildAt(i),active);}}
 @Override protected void onResume(){super.onResume();updateDock();View root=findViewById(android.R.id.content);if(root!=null)weatherRunning(root,true);}
 @Override protected void onPause(){View root=findViewById(android.R.id.content);if(root!=null)weatherRunning(root,false);super.onPause();}
}
